// Terrain is baked once; bucketed triangle interpolation also anchors scenery to it.
let terrainVertices=null,terrainCells=null;
function loadTerrain(){if(terrainCells)return;terrainCells=new Map();const data=CIRCUIT.elevation?.terrain;if(!data)return;const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));const raw=new Float32Array(bytes.buffer),clean=[];for(let k=0;k<raw.length;k+=9){const a=(raw[k+3]-raw[k])*(raw[k+8]-raw[k+2])-(raw[k+5]-raw[k+2])*(raw[k+6]-raw[k]);if(Math.abs(a)<.00001)continue;for(let j=0;j<9;j++)clean.push(raw[k+j])}terrainVertices=new Float32Array(clean);const v=terrainVertices;for(let i=0;i<v.length;i+=9){const minX=Math.floor(Math.min(v[i],v[i+3],v[i+6])/60),maxX=Math.floor(Math.max(v[i],v[i+3],v[i+6])/60),minZ=Math.floor(Math.min(v[i+2],v[i+5],v[i+8])/60),maxZ=Math.floor(Math.max(v[i+2],v[i+5],v[i+8])/60);for(let x=minX;x<=maxX;x++)for(let z=minZ;z<=maxZ;z++){const key=x+':'+z;if(!terrainCells.has(key))terrainCells.set(key,[]);terrainCells.get(key).push(i)}}}
function groundHeight(x,z){loadTerrain();const list=terrainCells.get(Math.floor(x/60)+':'+Math.floor(z/60)),v=terrainVertices;if(list)for(const i of list){const ax=v[i],az=v[i+2],bx=v[i+3],bz=v[i+5],dx=v[i+6],dz=v[i+8],den=(bz-dz)*(ax-dx)+(dx-bx)*(az-dz);const a=((bz-dz)*(x-dx)+(dx-bx)*(z-dz))/den,b=((dz-az)*(x-dx)+(ax-dx)*(z-dz))/den;if(a>=-1e-5&&b>=-1e-5&&a+b<=1.00001)return a*v[i+1]+b*v[i+4]+(1-a-b)*v[i+7]}return geography?geographicHeight(x,z):roadHeightAt(x,z)}
function trackHalf(i,side=1){const f=(i%N+N)%N,k=Math.floor(f),a=side>0?CIRCUIT.widthRight:CIRCUIT.widthLeft;return a?a[k]+(a[(k+1)%N]-a[k])*(f-k):W}
const trackBounds={x:Math.min(...cx),X:Math.max(...cx),z:Math.min(...cz),Z:Math.max(...cz)};
const circuitCentre={x:(trackBounds.x+trackBounds.X)/2,z:(trackBounds.z+trackBounds.Z)/2},circuitRadius=Math.hypot(trackBounds.X-trackBounds.x,trackBounds.Z-trackBounds.z)/2;
