 const contours=[a.local,...a.holes],flat=contours.flat(),tri=T.ShapeUtils.triangulateShape(a.local.map(p=>new T.Vector2(...p)),a.holes.map(h=>h.map(p=>new T.Vector2(...p)))),P=[],UV=[];
