 const zones=sponsorZones[CIRCUIT.id];zones.forEach(([fraction,name],brand)=>{const i=Math.round(fraction*N)%N,side=brand===0?-pitSide:-(Math.sign(CIRCUIT.line.curvature[i])||1);wrap(brand,i,urban?80:135,side,name);const target=urban?40:70,placed=wrap(brand,(i+Math.round(90/(LEN/N)))%N,target,-side,name+' exit'),missing=target-placed;if(missing>.001)wrap(brand,(i-Math.ceil((missing+20)/(LEN/N))+N)%N,missing,side,name+' approach');});
