 for(const f of pitFascias)for(let brand=0;brand<6;brand++){const pitch=f.length/6,w=Math.min(24,pitch*.88);panel(brand,f.group,(brand-2.5)*pitch,f.height-.65,f.z,w,Math.min(1.4,w/4),f.side<0?Math.PI:0,'pit building fascia',f.station,f.name);}
 const bridgeFraction={milano:.63,bahrain:.56,singapore:.10,monza:.70,monaco:.78,austria:.22,silverstone:.76,'abu-dhabi':.40,spa:.27,suzuka:.80,interlagos:.23,zandvoort:.51}[CIRCUIT.id];
 for(const [fraction,brand] of[[.012,rotation],[bridgeFraction,(rotation+3)%6]]){
  const i=Math.round(fraction*N)%N,left=trackBarrier(i,-1)-2,right=trackBarrier(i,1)+2,span=right-left,g=new T.Group();g.name='Partner bridge '+data[brand].name;g.position.set(cx[i],cy[i],cz[i]);g.rotation.y=-Math.atan2(tz[i],tx[i])-Math.PI/2;scene.add(g);
  const top=Math.max(9.5,Math.abs(Math.tan(bankAt(i)))*Math.max(Math.abs(left),right)+8),legs=[[left,top/2,0,.45,top,.65],[right,top/2,0,.45,top,.65],[(left+right)/2,top-.5,0,span,.55,1]],support=instanceBoxes(g,venueMetal,legs,true,false);boundInstances(support);
  for(const z of[-.53,.53])panel(brand,g,(left+right)/2,top-.5,z,Math.min(span,32),2.6,z<0?Math.PI:0,'overhead gantry',i,fraction===.012?'Start gantry':'Straight activation');
 }
 // Every runoff decal vertex follows the actual grade and bank.
 if(pavedRunoff&&!urban)zones.forEach(([fraction,name],k)=>{
  const brand=k,centre=Math.round(fraction*N)%N,side=-(Math.sign(CIRCUIT.line.curvature[centre])||1),half=trackHalf(centre,side),space=Math.abs(trackBarrier(centre,side))-half;if(space<16)return;
  const start=centre-2,end=centre+2,P=[],UV=[];let valid=true;const middle=side*(half+Math.min(space*.55,21)),width=Math.min(6,space*.32);
  for(let a=start;a<end;a++)for(const [st,edge]of[[a,-1],[a,1],[a+1,1],[a,-1],[a+1,1],[a+1,-1]]){const i=(st+N)%N,o=middle+edge*width/2,x=cx[i]+nx[i]*o,z=cz[i]+nz[i]*o,q=prog(x,z,i);if(Math.abs(q.d)<trackHalf(q.i,Math.sign(q.d))+2||Math.abs(q.d)>Math.abs(trackBarrier(q.i,Math.sign(q.d)))-2)valid=false;P.push(x,surfaceHeight(i,o)+.10,z);UV.push((st-start)/(end-start),(edge+1)/2)}
  if(!valid)return;const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(P,3));geo.setAttribute('uv',new T.Float32BufferAttribute(UV,2));geo.computeVertexNormals();geo.computeBoundingSphere();const m=new T.Mesh(geo,material(brand,(end-start)*LEN/N,width));m.receiveShadow=true;m.name=data[brand].name+' runoff artwork';scene.add(m);audit(brand,'terrain-fitted runoff artwork',centre,side,name);
 });
 for(const target of['#menu .menu-main','#results .panel']){const parent=document.querySelector(target);if(!parent||parent.querySelector('.team-partners'))continue;const strip=document.createElement('div');strip.className='team-partners';strip.setAttribute('aria-label','Milano Racing partners');for(let brand=0;brand<6;brand++){const img=document.createElement('img');img.alt=data[brand].name;img.src=texture(brand,4,1).image.toDataURL();strip.appendChild(img)}parent.appendChild(strip)}
