const raceMap=$('race-venue-map'),raceMapCtx=raceMap.getContext('2d');
function paintRaceVenue(){const x=CIRCUIT.x,z=CIRCUIT.z,minX=Math.min(...x),maxX=Math.max(...x),minZ=Math.min(...z),maxZ=Math.max(...z),scale=Math.min(530/(maxX-minX),320/(maxZ-minZ)),at=i=>[320+(x[i]-(minX+maxX)/2)*scale,210+(z[i]-(minZ+maxZ)/2)*scale];raceMapCtx.clearRect(0,0,640,420);raceMapCtx.lineJoin='round';raceMapCtx.lineCap='round';raceMapCtx.beginPath();for(let i=0;i<N;i++){const p=at(i);i?raceMapCtx.lineTo(...p):raceMapCtx.moveTo(...p)}raceMapCtx.closePath();raceMapCtx.strokeStyle='#0019ff';raceMapCtx.lineWidth=16;raceMapCtx.globalAlpha=.27;raceMapCtx.stroke();raceMapCtx.globalAlpha=1;raceMapCtx.strokeStyle='#e7ecf7';raceMapCtx.lineWidth=5;raceMapCtx.stroke();raceMapCtx.fillStyle='#ff7a00';raceMapCtx.beginPath();raceMapCtx.arc(...at(0),8,0,Math.PI*2);raceMapCtx.fill();$('race-venue-name').textContent=CIRCUIT.name;$('race-venue-length').textContent=(LEN/1000).toFixed(2);$('race-venue-turns').textContent=CIRCUIT.officialTurns;}
paintRaceVenue();
const difficultyBrief={rookie:'Braking assist. Room to learn.',club:'Light assistance. Faster rivals.',pro:'Full pace. Consistent rivals.',elite:'Maximum pace. Every tenth counts.'};
function updateSessionCard(){const difficulty=$('gp-difficulty').value,level=['rookie','club','pro','elite'].indexOf(difficulty);document.querySelectorAll('.difficulty-meter i').forEach((el,i)=>el.classList.toggle('active',i<=level));$('difficulty-brief').textContent=difficultyBrief[difficulty];const full=$('gp-length').value==='full',distance=full?'FULL DISTANCE':$('gp-length').value+' LAPS';$('race-session-summary').textContent='22 DRIVERS · '+distance+' · '+difficulty.toUpperCase();$('gp-start').textContent=mode==='qual'?'START QUALIFYING ↗':'TO THE GRID ↗';}
['gp-difficulty','gp-length','gp-qualifying','gp-start-tyre','gp-strategy'].forEach(id=>$(id).addEventListener('change',updateSessionCard));
document.querySelectorAll('[data-settings-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-settings-tab]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));document.querySelectorAll('[data-settings-panel]').forEach(p=>p.hidden=p.dataset.settingsPanel!==b.dataset.settingsTab)});
function syncInterfaceControls(){$('menu-steering').min=RG.steer[0];$('menu-steering').max=RG.steer[1];$('menu-steering').value=S.steer;$('menu-steering-value').value=S.steer.toFixed(2);$('menu-volume').value=S.vol;$('menu-volume-value').value=Math.round(S.vol*100)+'%';$('menu-mute').textContent=S.vol===0?'Unmute':'Mute';$('menu-racing-line').value=Math.round(S.line);}
$('menu-steering').oninput=e=>{S.steer=clamp(Number(e.target.value),RG.steer[0],RG.steer[1]);saveS();buildSL();syncInterfaceControls()};$('menu-volume').oninput=e=>{S.vol=clamp(Number(e.target.value),0,1);saveS();buildSL();syncInterfaceControls()};let previousVolume=.7;$('menu-mute').onclick=()=>{if(S.vol){previousVolume=S.vol;S.vol=0}else S.vol=previousVolume;saveS();buildSL();syncInterfaceControls()};$('menu-racing-line').onchange=e=>{S.line=+e.target.value;saveS();buildSL();syncInterfaceControls()};
function qualitySummary(){const names=graphicsPreset==='ultra'?[['Lighting','Full reflections'],['Shadows','4096 px'],['Resolution','125%'],['Finishing','AO + anti-aliasing']]:graphicsPreset==='high'?[['Lighting','HDR lighting'],['Shadows','2048 px'],['Resolution','100%'],['Finishing','AO + anti-aliasing']]:[['Lighting','HDR lighting'],['Shadows','Off'],['Resolution','100%'],['Priority','Frame rate']];$('quality-specs').innerHTML=names.map(([a,b])=>'<span>'+a+'<b>'+b+'</b></span>').join('')}
