let setupReturn='menu';const originalSetupStart=$('go').onclick;document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.weekend)updateSessionCard();if(el.dataset.go){setupReturn='menu';$('go').textContent='GO TO TRACK ↗';$('setup-back').dataset.ov='sessions'}if(el.dataset.setupFrom){setupReturn=el.dataset.setupFrom;$('go').textContent='APPLY SETUP ↗';$('setup-back').dataset.ov=setupReturn}if(el.dataset.ov==='settings')syncInterfaceControls()});$('go').onclick=()=>{if(setupReturn==='weekend'||setupReturn==='settings'){show(setupReturn);syncInterfaceControls()}else originalSetupStart()};
